def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""

    # Normalize available space in the stack
    if SH + 1 > 0:
        space_score = EMP / (SH + 1)
    else:
        space_score = 0.0

    # Compute similarity between average ID in stack and current retrieval ID
    if CUR + 1 > 0:
        avg_similarity = 1 - (abs(AVG - CUR) / (CUR + 1))
    else:
        avg_similarity = 0.0

    # Penalize stacks with more blocking containers
    if SH + 1 > 0:
        blocking_penalty = RI / (SH + 1)
    else:
        blocking_penalty = 0.0

    # Normalize stack height to encourage moderate fullness
    if SH + 1 > 0:
        height_score = SH / (SH + 1)
    else:
        height_score = 0.0

    # Use DIFF to prioritize stacks closer to the current retrieval order
    if DIFF + 1 > 0:
        diff_weight = 1 / (DIFF + 1)
    else:
        diff_weight = 0.0

    # Estimate future uncertainty
    uncertainty_estimate = diff_weight

    # Estimate retrieval foresight
    foresight_estimate = uncertainty_estimate

    # Normalize weights dynamically based on stack occupancy
    if EMP + 1 > 0:
        dynamic_weight = 1.0 / (1.0 + SH / (EMP + 1))
    else:
        dynamic_weight = 1.0

    # Compute final priority score
    priority = (1 - space_score) * dynamic_weight - avg_similarity + blocking_penalty - height_score - diff_weight - uncertainty_estimate - foresight_estimate * 2

    return priority
